```

And bootstrap.ts:
```typescript
export async function initializeKafkaRPC() {
  if (isKafkaRPCInitialized()) {
    return getKafkaService();
  }

  // Initialize Kafka service
  const kafkaService = new KafkaService();
  // ... set up handlers
  return kafkaService;
